"""Tests for the Airbnb silver transformation, including the geo postal code backfill."""

from pyspark.sql import DataFrame, Row, SparkSession
from shapely.geometry import Polygon

from revodata_assessment.geo import PostcodePolygon
from revodata_assessment.transformations.airbnb import clean_airbnb

_POLYGONS = [
    PostcodePolygon(pc4_code="1010", geometry=Polygon([(0, 0), (1, 0), (1, 1), (0, 1)])),
]

_COLUMNS = [
    "zipcode",
    "latitude",
    "longitude",
    "room_type",
    "accommodates",
    "bedrooms",
    "price",
    "review_scores_value",
]


def _bronze_airbnb(spark: SparkSession) -> DataFrame:
    # Row.__new__'s stub declares `*args: str`, but Row accepts any value at runtime;
    # the `None`s below (testing missing/unparsable values) trip ty's stricter check.
    rows = [
        # Full 6-character postal code: used as-is.
        Row("1052 AB", "0.9", "0.9", "Entire home/apt", "4", "2.0", "130", "100.0"),
        # Bare 4-digit postal code: used as-is.
        Row("1053", "0.8", "0.8", "Private room", "2", "1.0", "80", "90.0"),
        # Missing postal code but valid coordinates: backfilled via the polygon lookup.
        Row(None, "0.5", "0.5", "Private room", "2", "1.0", "59", "100.0"),  # ty: ignore[invalid-argument-type]
        # Unparsable postal code and coordinates outside all known polygons.
        Row("....", "5.0", "5.0", "Shared room", "1", "1.0", "40", None),  # ty: ignore[invalid-argument-type]
        # Exact duplicate of the first row: should be deduplicated away.
        Row("1052 AB", "0.9", "0.9", "Entire home/apt", "4", "2.0", "130", "100.0"),
    ]
    return spark.createDataFrame(rows, schema=_COLUMNS)


def test_clean_airbnb_deduplicates_exact_repeats(spark: SparkSession) -> None:
    """The duplicated listing is collapsed into a single row."""
    result = clean_airbnb(_bronze_airbnb(spark), _POLYGONS)
    assert result.count() == 4


def test_clean_airbnb_keeps_source_postal_codes(spark: SparkSession) -> None:
    """A 6-character or bare 4-digit source postal code is used without a geo lookup."""
    result = {
        row["nightly_price_eur"]: (row["postcode4"], row["postcode_source"])
        for row in clean_airbnb(_bronze_airbnb(spark), _POLYGONS).collect()
    }
    assert result[130.0] == ("1052", "source")
    assert result[80.0] == ("1053", "source")


def test_clean_airbnb_backfills_missing_postcode_from_coordinates(spark: SparkSession) -> None:
    """A missing postal code is backfilled from the point-in-polygon geo lookup."""
    result = {
        row["nightly_price_eur"]: (row["postcode4"], row["postcode_source"])
        for row in clean_airbnb(_bronze_airbnb(spark), _POLYGONS).collect()
    }
    assert result[59.0] == ("1010", "geo_backfill")


def test_clean_airbnb_leaves_unresolvable_rows_null(spark: SparkSession) -> None:
    """A row with no parsable postal code and coordinates outside every polygon stays null."""
    result = {
        row["nightly_price_eur"]: (row["postcode4"], row["postcode_source"])
        for row in clean_airbnb(_bronze_airbnb(spark), _POLYGONS).collect()
    }
    assert result[40.0] == (None, "unresolved")

"""Unit tests for the point-in-polygon postal code backfill in `revodata_assessment.geo`."""

import json
from pathlib import Path

from shapely.geometry import Polygon

from revodata_assessment.geo import PostcodePolygon, find_pc4_by_point, load_postcode_polygons

# Two adjacent unit squares, used instead of the real ~470-polygon dataset so
# these tests stay fast and their expected results are obvious by inspection.
_POLYGONS = [
    PostcodePolygon(pc4_code="1000", geometry=Polygon([(0, 0), (1, 0), (1, 1), (0, 1)])),
    PostcodePolygon(pc4_code="1001", geometry=Polygon([(1, 0), (2, 0), (2, 1), (1, 1)])),
]


def test_find_pc4_by_point_inside_first_polygon() -> None:
    """Matches a coordinate to the postal code of the polygon that contains it."""
    assert find_pc4_by_point(longitude=0.5, latitude=0.5, polygons=_POLYGONS) == "1000"


def test_find_pc4_by_point_inside_second_polygon() -> None:
    """Matches a coordinate against every polygon, not just the first one checked."""
    assert find_pc4_by_point(longitude=1.5, latitude=0.5, polygons=_POLYGONS) == "1001"


def test_find_pc4_by_point_outside_all_polygons() -> None:
    """Returns None when the coordinate falls outside every known polygon."""
    assert find_pc4_by_point(longitude=5.0, latitude=5.0, polygons=_POLYGONS) is None


def test_find_pc4_by_point_missing_coordinate() -> None:
    """Returns None when either coordinate is missing, rather than raising."""
    assert find_pc4_by_point(longitude=None, latitude=0.5, polygons=_POLYGONS) is None
    assert find_pc4_by_point(longitude=0.5, latitude=None, polygons=_POLYGONS) is None


def test_load_postcode_polygons(tmp_path: Path) -> None:
    """Loads polygons and their pc4_code from a GeoJSON file, matching the reference format."""
    geojson_path = tmp_path / "post_codes.geojson"
    geojson_path.write_text(
        json.dumps(
            {
                "type": "FeatureCollection",
                "features": [
                    {
                        "type": "Feature",
                        "properties": {"pc4_code": "1052"},
                        "geometry": {
                            "type": "Polygon",
                            "coordinates": [[[0, 0], [1, 0], [1, 1], [0, 1], [0, 0]]],
                        },
                    },
                ],
            }
        ),
        encoding="utf-8",
    )

    polygons = load_postcode_polygons(str(geojson_path))

    assert len(polygons) == 1
    assert polygons[0].pc4_code == "1052"
    assert polygons[0].geometry.contains(polygons[0].geometry.centroid)

