@lru_cache(maxsize=4)
def _load_postcode_polygons_on_worker(geojson_filename: str) -> list[PostcodePolygon]:
    """Load and cache postal code polygons once per executor Python process.

    `geojson_filename` is resolved via `SparkFiles.get`, so this works whether
    the file lives on shared workspace storage or was shipped to the cluster
    with `spark.addArtifact(path, file=True)` (see `silver_airbnb`). The
    `lru_cache` means repeated pandas UDF batches on the same worker reuse the
    parsed polygons instead of re-parsing the GeoJSON file every batch.
    """
    return load_postcode_polygons(SparkFiles.get(geojson_filename))


def make_postcode_lookup_udf(geojson_filename: str) -> UserDefinedFunction:
    """Build a pandas UDF that backfills postal codes from longitude/latitude pairs.

    Takes a filename resolved on the worker (via `SparkFiles.get`) rather than
    pre-built polygons, so the UDF's closure stays a few bytes instead of
    shipping ~470 already-built Shapely geometries from the driver through a
